        {
            return;
        }

        var ms = (int)Math.Round(vp.Position * 1000 - selectedSubtitle.StartTime.TotalMilliseconds, MidpointRounding.AwayFromZero);

        await ClipboardHelper.SetTextAsync(Window, ms.ToString(CultureInfo.InvariantCulture));
    }

