    /// <summary>
    /// SE 4 parity ("guess start"): looks for the silence right before the speech that starts the
    /// selected line and moves the start cue there, snapping to a nearby shot change when there is
    /// one. Raising the volume threshold step by step finds the quietest boundary that still reads
    /// as silence. Moving the start forward keeps the duration when that would otherwise break the
    /// minimum duration/maximum CPS rules and there is room before the next line.
    /// </summary>
    [RelayCommand]
    private void WaveformGuessStart()
    {
        var selected = SelectedSubtitle;
        if (selected == null || AreTimeCodesLocked || AudioVisualizer?.WavePeaks == null)
        {
            return;
        }

        var index = Subtitles.IndexOf(selected);
        if (index < 0)
        {
            return;
        }

        const double silenceLengthInSeconds = 0.08;
        var startSeconds = selected.StartTime.TotalSeconds;
        var lowPercent = AudioVisualizer.FindLowPercentage(startSeconds - 0.3, startSeconds + 0.1);
        var highPercent = AudioVisualizer.FindHighPercentage(startSeconds - 0.3, startSeconds + 0.4);
        var add = 5.0;
        if (highPercent > 40)
        {
            add = 8;
        }
        else if (highPercent < 5)
        {
            add = highPercent - lowPercent - 0.3;
        }

        var gapMs = Se.Settings.General.MinimumBetweenLines.GetMilliseconds();
        var prev = GetPreviousWorkingRow(index);
        var next = GetNextWorkingRow(index);

        for (var startVolume = lowPercent + add; startVolume < 14; startVolume += 0.3)
        {
            var pos = AudioVisualizer.FindDataBelowThresholdBackForStart(startVolume, silenceLengthInSeconds, startSeconds);
            if (pos < 0 || pos <= startSeconds - 1)
            {
                continue;
            }

            // A slightly higher threshold that still lands inside the same silence is the
            // better guess - it sits closer to the speech.
            var pos2 = AudioVisualizer.FindDataBelowThresholdBackForStart(startVolume + 0.3, silenceLengthInSeconds, startSeconds);
            if (pos2 > pos && pos2 > startSeconds - 1)
            {
                pos = pos2;
            }

            var newStartMs = pos * TimeCode.BaseUnit;
            if (prev != null && prev.EndTime.TotalMilliseconds + gapMs >= newStartMs)
            {
                newStartMs = prev.EndTime.TotalMilliseconds + gapMs;
                if (newStartMs >= selected.StartTime.TotalMilliseconds)
                {
                    break; // cannot move the start time
                }
            }

            var shotChanges = AudioVisualizer.ShotChanges;
            if (shotChanges.Count > 0)
            {
                var nearestShotChange = shotChanges
                    .Where(sc => sc > startSeconds - 0.3 && sc < startSeconds + 0.2)
                    .OrderBy(sc => Math.Abs(sc - startSeconds))
                    .Take(1)
                    .ToList();
                if (nearestShotChange.Count > 0)
                {
                    newStartMs = nearestShotChange[0] * TimeCode.BaseUnit;
                }
            }

            if (Math.Abs(selected.StartTime.TotalMilliseconds - newStartMs) < 10)
            {
                break; // difference too small
            }

            var durationMs = selected.EndTime.TotalMilliseconds - selected.StartTime.TotalMilliseconds;
            var newEndMs = selected.EndTime.TotalMilliseconds;
            if (newStartMs > selected.StartTime.TotalMilliseconds)
            {
                var newStart = TimeSpanExtensions.FromMillisecondsWholeMilliseconds(newStartMs);
                var newCps = SubtitleTextInfoHelper.GetCharactersPerSecond(selected.Text, newStart, selected.EndTime);
                if (newEndMs - newStartMs < Se.Settings.General.SubtitleMinimumDisplayMilliseconds ||
                    newCps > Se.Settings.General.SubtitleMaximumCharactersPerSeconds)
                {
                    // Shortening the line would break the rules, so move it instead - but only
                    // when the next line is far enough away to take the whole duration.
                    if (next == null || next.StartTime.TotalMilliseconds > newStartMs + durationMs + gapMs)
                    {
                        newEndMs = newStartMs + durationMs;
                    }
                }
            }

            selected.SetTimes(
                TimeSpanExtensions.FromMillisecondsWholeMilliseconds(newStartMs),
                TimeSpanExtensions.FromMillisecondsWholeMilliseconds(newEndMs));

            _updateAudioVisualizer = true;
            break;
        }
    }

    [RelayCommand]
    private async Task WaveformExtractAudio()
    {
        if (Window == null || string.IsNullOrEmpty(_videoFileName))
        {
            return;
        }

        var selectedItems = SubtitleGridSelectedItems.Cast<SubtitleLineViewModel>().ToList();
        if (selectedItems.Count != 1)
        {
            return;
        }

        var ffmpegOk = await RequireFfmpegOk();
        if (!ffmpegOk)
        {
            return;
        }

        var line = selectedItems[0];

        // Offer the configured format first in the Save dialog, then the rest; the
        // user can still switch the type there (issues #11235 / #11237).
        var configuredFormat = NormalizeExtractAudioFormat(Se.Settings.Waveform.ExtractAudioFormat);
        var fileTypes = ExtractAudioFileTypes(configuredFormat);
        var suggestedName = $"{Path.GetFileNameWithoutExtension(_videoFileName)}_{line.Number}.{configuredFormat}";
        var outputFileName = await _fileHelper.PickSaveFile(Window, fileTypes, suggestedName, Se.Language.Waveform.ExtractAudioDotDotDot);
        if (string.IsNullOrEmpty(outputFileName))
        {
            return;
        }

        try
        {
            // The actual output format is whatever extension the file ended up with
            // (the user may have changed the type in the dialog). ffmpeg picks the
            // codec from the extension; bitrate only applies to lossy formats.
            var chosenFormat = NormalizeExtractAudioFormat(Path.GetExtension(outputFileName).TrimStart('.'));
            var sampleRate = Se.Settings.Waveform.ExtractAudioSampleRate;
            var bitRate = IsLossyAudioFormat(chosenFormat) ? Se.Settings.Waveform.ExtractAudioBitRate : string.Empty;

            var arguments = FfmpegGenerator.ExtractAudioClipFromVideoParameters(
                _videoFileName,
                line.StartTime.TotalSeconds,
                line.Duration.TotalSeconds,
                false,
                outputFileName,
                _audioTrack?.FfIndex ?? -1,
                sampleRate,
                bitRate);

            using var process = FfmpegGenerator.GetProcess(arguments, (_, _) => { });
            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();
            await Task.Run(() => process.WaitForExit());

            if (process.ExitCode != 0 || !File.Exists(outputFileName))
            {
                await MessageBox.Show(Window, Se.Language.General.Error, "Could not extract audio clip from video.", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            await ShowDialogAsync<PromptFileSavedWindow, PromptFileSavedViewModel>(vm =>
            {
                vm.Initialize(
                    Se.Language.General.FileSaved,
                    string.Format(Se.Language.General.FileSavedToX, outputFileName),
                    outputFileName,
                    true,
                    true);
            });
        }
        catch (Exception exception)
        {
            await MessageBox.Show(Window, Se.Language.General.Error, exception.Message, MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    // Output formats offered by the waveform "Extract audio..." action. Order here is the
    // fallback order; the user's configured format is always moved to the front.
    private static readonly string[] ExtractAudioFormats = { "wav", "mp3", "m4a", "flac" };

    private static string NormalizeExtractAudioFormat(string? format)
    {
        var f = format?.Trim().ToLowerInvariant();
        return !string.IsNullOrEmpty(f) && ExtractAudioFormats.Contains(f) ? f! : "wav";
    }

    private static bool IsLossyAudioFormat(string format) => format is "mp3" or "m4a";

    private static IReadOnlyList<(string Name, string Extension)> ExtractAudioFileTypes(string preferredFormat)
    {
        string DisplayName(string f) => f switch
        {
            "wav" => "WAV",
            "mp3" => "MP3",
            "m4a" => "M4A (AAC)",
            "flac" => "FLAC",
            _ => f.ToUpperInvariant(),
        };

        // Preferred format first so it's the dialog's default selection.
        var ordered = new List<string> { preferredFormat };
        ordered.AddRange(ExtractAudioFormats.Where(f => f != preferredFormat));
        return ordered.Select(f => (DisplayName(f), "." + f)).ToList();
    }

    /// <summary>
    /// Clones the voice heard in the selected subtitle line into <paramref name="engine"/>'s
    /// voices, so it can be picked for dubbing in the text-to-speech window (#13698).
    /// </summary>
    /// <remarks>
    /// The short way round what used to be "extract audio to a file, open text to speech, pick the
    /// engine, open voice settings, import, find the file again". Two things are known here that
    /// the import dialog has to ask for: the audio (it is the line's own time range in the video's
    /// current audio track) and the reference text (it is the line's text), so the engines that
    /// want a transcript get a correct one without a Whisper round trip.
    /// </remarks>
    [RelayCommand]
    private async Task WaveformCloneVoiceToEngine(ITtsEngine? engine)
    {
        if (Window == null || engine == null || string.IsNullOrEmpty(_videoFileName))
        {
            return;
        }

        var selectedItems = SubtitleGridSelectedItems.Cast<SubtitleLineViewModel>().ToList();
        if (selectedItems.Count != 1)
        {
            return;
        }

        var line = selectedItems[0];

        // Asked before anything else happens, so a user who declines is not first made to name a
        // voice. Shown once ever - see VoiceCloningConsent.
        var consentOk = await VoiceCloneConsentPrompt.EnsureAsync(
            engine,
            Window,
            () => ShowDialogAsync<VoiceCloneConsentWindow, VoiceCloneConsentViewModel>(_ => { }));
        if (!consentOk)
        {
            return;
        }

        if (!await RequireFfmpegOk())
        {
            return;
        }

        var nameResult = await ShowDialogAsync<PromptTextBoxWindow, PromptTextBoxViewModel>(vm =>
            vm.Initialize(
                Se.Language.Waveform.CloneVoiceNameTitle,
                SuggestCloneVoiceName(line),
                300,
                30,
                returnSubmits: true));
        if (!nameResult.OkPressed || string.IsNullOrWhiteSpace(nameResult.Text))
        {
            return;
        }

        // The engines name the imported voice after the file they are handed, so the name the user
        // typed has to survive as a file name.
        var voiceName = MakeSafeVoiceFileName(nameResult.Text);
        var tempFolder = Path.Combine(Path.GetTempPath(), "SeVoiceClone_" + Guid.NewGuid().ToString("N"));
        var clipFileName = Path.Combine(tempFolder, voiceName + ".wav");

        try
        {
            Directory.CreateDirectory(tempFolder);

            // Source sample rate and no bit rate: the clip is a lossless hand-off, and every
            // cloning engine resamples it to whatever its backend wants on import.
            var arguments = FfmpegGenerator.ExtractAudioClipFromVideoParameters(
                _videoFileName,
                line.StartTime.TotalSeconds,
                line.Duration.TotalSeconds,
                false,
                clipFileName,
                _audioTrack?.FfIndex ?? -1,
                0,
                string.Empty);

            using (var process = FfmpegGenerator.GetProcess(arguments, (_, _) => { }))
            {
                process.Start();
                process.BeginOutputReadLine();
                process.BeginErrorReadLine();
                await Task.Run(() => process.WaitForExit());

                if (process.ExitCode != 0 || !File.Exists(clipFileName))
                {
                    await MessageBox.Show(Window, Se.Language.General.Error, Se.Language.Waveform.CloneVoiceExtractFailed, MessageBoxButtons.OK, MessageBoxIcon.Error);
                    return;
                }
            }

            var transcript = HtmlUtil.RemoveHtmlTags(line.Text ?? string.Empty, true)
                .Replace('\n', ' ')
                .Replace('\r', ' ')
                .Trim();
            var imported = await Task.Run(() => VoiceCloneImporter.Import(engine, clipFileName, transcript));
            if (!imported)
            {
                await MessageBox.Show(
                    Window,
                    Se.Language.General.Error,
                    string.Format(Se.Language.Video.TextToSpeech.VoiceXCouldNotBeImported, voiceName),
                    MessageBoxButtons.OK,
                    MessageBoxIcon.Error);
                return;
            }

            await MessageBox.Show(
                Window,
                Se.Language.Video.TextToSpeech.VoiceImportSuccessTitle,
                string.Format(Se.Language.Video.TextToSpeech.VoiceXImported, voiceName));
        }
        catch (Exception exception)
        {
            await MessageBox.Show(Window, Se.Language.General.Error, exception.Message, MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
        finally
        {
            try
            {
                if (Directory.Exists(tempFolder))
                {
                    Directory.Delete(tempFolder, true);
                }
            }
            catch
            {
                // A leftover clip in the temp folder is not worth telling the user about.
            }
        }
    }

    /// <summary>
    /// The name offered for a voice cloned from <paramref name="line"/>: the actor, if the line
    /// names one (that is what the user calls this voice anyway), otherwise the video and the line
    /// number, which at least says where the voice came from.
    /// </summary>
    private string SuggestCloneVoiceName(SubtitleLineViewModel line)
    {
        var actor = (line.Actor ?? string.Empty).Trim();
        if (actor.Length > 0)
        {
            return actor;
        }

        var videoName = Path.GetFileNameWithoutExtension(_videoFileName);
        return string.IsNullOrEmpty(videoName) ? $"voice_{line.Number}" : $"{videoName}_{line.Number}";
    }

    private static string MakeSafeVoiceFileName(string name)
    {
        var safe = new string(name.Trim()
            .Select(c => Path.GetInvalidFileNameChars().Contains(c) ? '_' : c)
            .ToArray());

        // A name that was nothing but path characters would leave an empty file name.
        return string.IsNullOrWhiteSpace(safe) ? "voice" : safe;
    }

    [RelayCommand]
    private async Task WaveformToggleWaveformSpectrogramHeight()
    {
        if (Window == null || AudioVisualizer?.WavePeaks == null)
        {
            return;
        }

        Se.Settings.Waveform.SpectrogramCombinedWaveformHeight += 10;
        if (Se.Settings.Waveform.SpectrogramCombinedWaveformHeight > 90)
        {
            Se.Settings.Waveform.SpectrogramCombinedWaveformHeight = 10;
        }

        AudioVisualizer.WaveformHeightPercentage = Se.Settings.Waveform.SpectrogramCombinedWaveformHeight;
        AudioVisualizer.ResetCache();
        _updateAudioVisualizer = true;
    }

    [RelayCommand]
    private async Task SpectrogramToggleStyle()
    {
        if (Window == null || AudioVisualizer == null || AudioVisualizer?.WavePeaks == null || string.IsNullOrEmpty(_videoFileName))
        {
            return;
        }

        var currentStyle = Se.Settings.Waveform.SpectrogramStyle;

        // Cycle through available spectrogram styles
        if (currentStyle == nameof(SeSpectrogramStyle.Classic))
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.ClassicViridis);
        }
        else if (currentStyle == nameof(SeSpectrogramStyle.ClassicViridis))
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.ClassicPlasma);
        }
        else if (currentStyle == nameof(SeSpectrogramStyle.ClassicPlasma))
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.ClassicInferno);
        }
        else if (currentStyle == nameof(SeSpectrogramStyle.ClassicInferno))
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.ClassicTurbo);
        }
        else if (currentStyle == nameof(SeSpectrogramStyle.ClassicTurbo))
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.Neon);
        }
        else // Neon or any other value, cycle back to Classic
        {
            Se.Settings.Waveform.SpectrogramStyle = nameof(SeSpectrogramStyle.Classic);
        }

        var spectrogramFileName = WavePeakGenerator2.SpectrogramDrawer.GetSpectrogramFileName(_videoFileName, _audioTrack?.FfIndex ?? -1);
        if (File.Exists(spectrogramFileName))
        {
            var spectrogram = SpectrogramData2.FromDisk(spectrogramFileName);
            if (spectrogram != null)
            {
                spectrogram.Load();
                AudioVisualizer.SetSpectrogram(spectrogram);
            }

            AudioVisualizer.ResetCache();
            _updateAudioVisualizer = true;
        }

        ShowStatus(AddSpaceBeforeUppercaseLetter(Se.Settings.Waveform.SpectrogramStyle));
    }

    private string AddSpaceBeforeUppercaseLetter(string spectrogramStyle)
    {
        var sb = new StringBuilder();
        for (var i = 0; i < spectrogramStyle.Length; i++)
        {
            var c = spectrogramStyle[i];
            if (i > 0 && char.IsUpper(c) && !char.IsUpper(spectrogramStyle[i - 1]))
            {
                sb.Append(' ');
            }

            sb.Append(c);
        }

        return sb.ToString().Trim();
    }

    [RelayCommand]
    private async Task ShowWaveformGuessTimeCodes()
    {
        var vp = GetVideoPlayerControl();
        if (Window == null || AudioVisualizer?.WavePeaks == null || vp == null)
        {
            return;
        }

        var result = await ShowDialogAsync<WaveformGuessTimeCodesWindow, WaveformGuessTimeCodesViewModel>();

        if (!result.OkPressed ||
            !result.ScanBlockSize.HasValue ||
            !result.ScanBlockAverageMin.HasValue ||
            !result.ScanBlockAverageMax.HasValue ||
            !result.SplitLongSubtitlesAtMs.HasValue)
        {
            _shortcutManager.ClearKeys();
            return;
        }

        double startFromSeconds = 0;
        if (result.StartFromVideoPosition)
        {
            startFromSeconds = vp.Position;
        }

        if (result.DeleteLinesAll)
        {
            _subtitle.Paragraphs.Clear();
        }
        else if (result.DeleteLinesFromVideoPosition)
        {
            // New time codes are generated from the video position onward, so the existing
            // lines from that position are the ones to delete - the lines BEFORE it are kept
            // (this used to be inverted, wiping the user's work before the position and
            // doubling up lines after it).
            var subsToKeep = Subtitles.Where(p => p.StartTime.TotalSeconds < vp.Position).ToList();
            _subtitle.Paragraphs.Clear();
            // Pass the format so Paragraph.Extra keeps the ASSA style - SetSubtitles below
            // rebuilds the rows from these paragraphs and reads the style back from Extra.
            _subtitle.Paragraphs.AddRange(subsToKeep.Select(p => p.ToParagraph(SelectedSubtitleFormat)));
        }

        AudioVisualizer.GenerateTimeCodes(_subtitle, startFromSeconds, result.ScanBlockSize.Value, result.ScanBlockAverageMin.Value, result.ScanBlockAverageMax.Value,
            result.SplitLongSubtitlesAtMs.Value);
        SetSubtitles(_subtitle);
    }

    [RelayCommand]
    private async Task RecalculateDurationSelectedLines()
    {
        var selectedLines = SubtitleGridSelectedItems.Cast<SubtitleLineViewModel>().ToList();
        if (selectedLines.Count == 0)
        {
            return;
        }

        foreach (var selectedLine in selectedLines)
        {
            var idx = Subtitles.IndexOf(selectedLine);
            if (idx < 0)
            {
                continue;
            }

            var nextSubtitle = GetNextWorkingRow(idx);
            // Count like the grid's CPS column does (tags and line breaks stripped)
            var charCount = (double)(selectedLine.Text ?? string.Empty).CountCharacters(true);

            var optimalDuration = TimeSpanExtensions.FromSecondsWholeMilliseconds(charCount / Se.Settings.General.SubtitleOptimalCharactersPerSeconds);
            var maxDuration = TimeSpanExtensions.FromSecondsWholeMilliseconds(charCount / Se.Settings.General.SubtitleMaximumCharactersPerSeconds);
            var maxEndTime = TimeSpan.FromMilliseconds(selectedLine.StartTime.TotalMilliseconds + Se.Settings.General.SubtitleMaximumDisplayMilliseconds);
            if (nextSubtitle != null)
            {
                var tempMaxEntTime = TimeSpan.FromMilliseconds(nextSubtitle.StartTime.TotalMilliseconds - Se.Settings.General.MinimumBetweenLines.GetMilliseconds());
                if (tempMaxEntTime < maxEndTime)
                {
                    maxEndTime = tempMaxEntTime;
                }
            }

            var proposedEndTime = selectedLine.StartTime + optimalDuration;
            if (proposedEndTime.TotalMilliseconds - selectedLine.StartTime.TotalMilliseconds < Se.Settings.General.SubtitleMinimumDisplayMilliseconds)
            {
                proposedEndTime = TimeSpan.FromMilliseconds(selectedLine.StartTime.TotalMilliseconds + Se.Settings.General.SubtitleMinimumDisplayMilliseconds);
            }

            var fallbackEndTime = selectedLine.StartTime + maxDuration;

            if (proposedEndTime <= maxEndTime)
            {
                selectedLine.EndTime = proposedEndTime;
            }
            else if (fallbackEndTime <= maxEndTime)
            {
                selectedLine.EndTime = fallbackEndTime;
            }
        }

        _updateAudioVisualizer = true;
    }

    [RelayCommand]
    private void SetDurationMaxCpsSelectedLines()
    {
        var selectedLines = SubtitleGridSelectedItems.Cast<SubtitleLineViewModel>().ToList();
        if (selectedLines.Count == 0)
        {
            return;
        }

        foreach (var selectedLine in selectedLines)
        {
            var idx = Subtitles.IndexOf(selectedLine);
            if (idx < 0)
            {
                continue;
            }

            // Count like the grid's CPS column does (tags and line breaks stripped)
            var charCount = (double)(selectedLine.Text ?? string.Empty).CountCharacters(true);
            if (charCount <= 0)
            {
                continue;
            }

            var maxCps = Se.Settings.General.SubtitleMaximumCharactersPerSeconds;
            if (maxCps <= 0)
            {
                continue;
            }

            var minEndTime = TimeSpan.FromMilliseconds(selectedLine.StartTime.TotalMilliseconds + Se.Settings.General.SubtitleMinimumDisplayMilliseconds);
            var maxEndTime = TimeSpan.FromMilliseconds(selectedLine.StartTime.TotalMilliseconds + Se.Settings.General.SubtitleMaximumDisplayMilliseconds);
            var nextSubtitle = GetNextWorkingRow(idx);
            if (nextSubtitle != null)
            {
                var gapBound = TimeSpan.FromMilliseconds(nextSubtitle.StartTime.TotalMilliseconds - Se.Settings.General.MinimumBetweenLines.GetMilliseconds());
                if (gapBound < maxEndTime)
                {
                    maxEndTime = gapBound;
                }
            }

            if (maxEndTime < minEndTime)
            {
                continue;
            }

            var newEndTime = selectedLine.StartTime + TimeSpanExtensions.FromSecondsWholeMilliseconds(charCount / maxCps);
            if (newEndTime < minEndTime)
            {
                newEndTime = minEndTime;
            }
            if (newEndTime > maxEndTime)
            {
                newEndTime = maxEndTime;
            }

            selectedLine.EndTime = newEndTime;
        }

        _updateAudioVisualizer = true;
    }

